function diameter(root) {
  let best = 0;

  const height = (node) => {
    let first = 0;
    let second = 0;
    for (const child of node.children) {
      const down = height(child) + 1;
      if (down > first) {
        second = first;
        first = down;
      } else if (down > second) {
        second = down;
      }
    }
    best = Math.max(best, first + second);
    return first;
  };

  height(root);
  return best;
}

