function diameter(root) {
  // Turn the tree into an undirected graph, then run a breadth-first search from every node.
  const nodes = [root];
  const adjacent = [[]];
  for (let k = 0; k < nodes.length; k++) {
    for (const child of nodes[k].children) {
      const id = nodes.length;
      nodes.push(child);
      adjacent.push([k]);
      adjacent[k].push(id);
    }
  }
  let longest = 0;
  for (let start = 0; start < nodes.length; start++) {
    const dist = new Array(nodes.length).fill(-1);
    dist[start] = 0;
    const order = [start];
    for (let q = 0; q < order.length; q++) {
      for (const next of adjacent[order[q]]) {
        if (dist[next] === -1) { dist[next] = dist[order[q]] + 1; order.push(next); longest = Math.max(longest, dist[next]); }
      }
    }
  }
  return longest;
}

